#if VERSIONMAC
static bool checkAccess(PA_ObjectRef status) {
        
    bool entitlement = false;
    
    /*
     
     https://developer.apple.com/documentation/bundleresources/entitlements/com_apple_security_smartcard
     
     */
    
    SecTaskRef sec = SecTaskCreateFromSelf(kCFAllocatorDefault);
    if(!sec) {
        return false;
    }
    CFErrorRef err = NULL;
    CFTypeRef value = SecTaskCopyValueForEntitlement(sec,
                                                     CFSTR("com.apple.security.smartcard"),
                                                     &err);
    if(!err) {
        if((value) && (CFGetTypeID(value) == CFBooleanGetTypeID())) {
            entitlement = CFBooleanGetValue((CFBooleanRef)value);
        }
    }

    /* Copy rule: both are owned by the caller */
    if(value) CFRelease(value);
    if(err) CFRelease(err);
    CFRelease(sec);
        
    return entitlement;
}
#endif

